CREATE TABLE book (
  book_id integer PRIMARY KEY,
  title   text NOT NULL,
  price   numeric(6, 2) NOT NULL CHECK (price > 0)
);

INSERT INTO book (book_id, title, price)
VALUES (1, 'SQL Basics', 29.90),
       (2, 'Data Models', 45.00),
       (3, 'Joins Explained', 19.50);

SELECT title, price FROM book ORDER BY book_id;

CREATE TABLE shift (
  shift_id    integer PRIMARY KEY,
  employee_id integer NOT NULL REFERENCES employees (employee_id),
  hours       numeric(4, 1) NOT NULL CHECK (hours > 0 AND hours <= 12),
  shift_date  date NOT NULL DEFAULT DATE '1998-06-01'
);

INSERT INTO shift (shift_id, employee_id, hours)
VALUES (1, 1, 8), (2, 2, 6.5);
INSERT INTO shift (shift_id, employee_id, hours, shift_date)
VALUES (3, 1, 4, '1998-06-02');

SELECT s.shift_id, e.last_name, s.hours, s.shift_date
FROM shift s
JOIN employees e ON e.employee_id = s.employee_id
ORDER BY s.shift_id;

