CREATE TABLE price_band (
  band text PRIMARY KEY,
  low  numeric(8, 2) NOT NULL,
  high numeric(8, 2) NOT NULL,
  CHECK (high > low)
);

INSERT INTO price_band (band, low, high)
VALUES ('budget', 0, 10), ('standard', 10, 30), ('premium', 30, 1000);

SELECT b.band, COUNT(*) AS products, ROUND(AVG(p.unit_price), 2) AS avg_price
FROM products p
JOIN price_band b ON p.unit_price >= b.low AND p.unit_price < b.high
GROUP BY b.band, b.low
ORDER BY b.low;
